result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/minimake.py", "content": "#!/usr/bin/env python3
"""minimake.py -- a from-scratch build system with checksum-based incrementality.

Reads a build graph from build.json:
    [
      {"target": "out/final.txt",
       "deps": ["out/a.txt", "src/b.txt"],
       "cmd": "cat out/a.txt src/b.txt > out/final.txt"},
      ...
    ]

Rules:
  * Targets are built in topological order (deps before dependents).
  * A target is rebuilt only if it is missing, its cmd changed, or the
    sha256 of any dep (or the dep's recorded absence) changed since the
    last successful build.
  * Build state lives in .minimake.db as JSON.
  * Prints "REBUILD <target>" or "UP-TO-DATE <target>" per target.
  * Cycles in the dependency graph are detected and reported as errors.
"""

import hashlib
import json
import subprocess
import sys
from pathlib import Path

DB_PATH = ".minimake.db"


def sha256_of(path: Path) -> str | None:
    """Return hex digest of a file's contents, or None if it doesn't exist."""
    if not path.exists():
        return None
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def load_db() -> dict:
    p = Path(DB_PATH)
    if not p.exists():
        return {}
    try:
        return json.loads(p.read_text())
    except json.JSONDecodeError:
        # Corrupt db: start fresh rather than failing the build.
        return {}


def save_db(db: dict) -> None:
    Path(DB_PATH).write_text(json.dumps(db, indent=2, sort_keys=True))


def topo_sort(rules: list[dict]) -> list[dict]:
    """Order rules so every rule comes after all of its deps that are targets.

    Raises ValueError on unknown deps or cycles.
    """
    by_target = {r["target"]: r for r in rules}
    if len(by_target) != len(rules):
        raise ValueError("duplicate target definitions in build.json")

    state = {}  # target -> 0=visiting, 1=done
    order = []

    def visit(rule):
        t = rule["target"]
        mark = state.get(t)
        if mark == 1:
            return
        if mark == 0:
            raise ValueError(f"dependency cycle detected involving '{t}'")
        state[t] = 0
        for dep in rule.get("deps", []):
            if dep not in by_target:
                continue  # source file, not a build target
            visit(by_target[dep])
        state[t] = 1
        order.append(rule)

    for r in rules:
        visit(r)
    return order


def needs_rebuild(rule: dict, db: dict) -> bool:
    """True if target is missing, cmd changed, or any dep checksum changed."""
    record = db.get(rule["target"])
    if record is None:
        return True
    if record.get("cmd") != rule.get("cmd"):
        return True
    target = Path(rule["target"])
    if not target.exists():
        return True
    old_hashes = record.get("dep_hashes", {})
    for dep in rule.get("deps", []):
        current = sha256_of(Path(dep))
        if old_hashes.get(dep) != current:
            return True
    return False


def run_cmd(cmd: str) -> None:
    proc = subprocess.run(cmd, shell=True)
    if proc.returncode != 0:
        sys.exit(f"minimake: command failed (exit {proc.returncode}): {cmd}")


def build(build_file: str = "build.json") -> list[str]:
    """Run the build. Returns list of status lines like 'REBUILD <target>'."""
    rules = json.loads(Path(build_file).read_text())
    order = topo_sort(rules)

    # Sanity: every dep must exist after its producers ran; check sources up front.
    targets = {r["target"] for r in rules}
    db = load_db()
    lines = []
    new_db = {k: v for k, v in db.items() if k in targets}

    for rule in order:
        target = rule["target"]
        missing_src = [
            d for d in rule.get("deps", [])
            if d not in targets and not Path(d).exists()
        ]
        if missing_src:
            sys.exit(f"minimake: no rule to make '{target}': "
                     f"missing source(s): {', '.join(missing_src)}")
        if needs_rebuild(rule, db):
            run_cmd(rule["cmd"])
            if not Path(target).exists():
                sys.exit(f"minimake: rule for '{target}' did not produce its target")
            new_db[target] = {
                "cmd": rule.get("cmd"),
                "dep_hashes": {
                    d: sha256_of(Path(d)) for d in rule.get("deps", [])
                },
            }
            lines.append(f"REBUILD {target}")
        else:
            lines.append(f"UP-TO-DATE {target}")

    save_db(new_db)
    return lines


def main(argv: list[str]) -> int:
    build_file = argv[1] if len(argv) > 1 else "build.json"
    for line in build(build_file):
        print(line)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
